import React from 'react';

function Studio() {
  return (
    <div className="container" style={{ padding: 20 }}>
      <h1>📸 협찬 스튜디오 (Mini 협찬 시뮬레이터)</h1>
      <p style={{ color: '#555' }}>크리에이터를 위한 협찬/콘텐츠 제작 툴(간단한 시뮬레이터) 플레이스홀더입니다.</p>

      <div style={{ marginTop: 20 }}>
        <div style={{ padding: 16, border: '1px dashed #e6eefb', borderRadius: 10 }}>
          <p className="muted">샘플 콘텐츠 생성 · 협찬 제안서 템플릿 · 제출 가이드 등을 이 영역에 구현할 수 있습니다.</p>
        </div>
      </div>
    </div>
  );
}

export default Studio;
